  <script>
      function openIsoCertModal(e) {
          if (e && e.preventDefault) {
              e.preventDefault();
          }
          var modal = document.getElementById('isoCertModal');
          var iframe = document.getElementById('isoCertIframe');
          var pdfUrl = "{{ url('/sortiq-solutions-iso-9001-certificate.pdf') }}";
          if (modal && iframe) {
              if (!iframe.src || iframe.src === 'about:blank' || iframe.src === window.location.href) {
                  iframe.src = pdfUrl + '#toolbar=1&navpanes=0';
              }
              modal.style.display = 'flex';
              document.body.style.overflow = 'hidden';
          }
      }
      function closeIsoCertModal() {
          var modal = document.getElementById('isoCertModal');
          if (modal) {
              modal.style.display = 'none';
              document.body.style.overflow = '';
          }
      }
      document.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
              closeIsoCertModal();
          }
      });
      document.getElementById('isoCertModal')?.addEventListener('click', function(e) {
          if (e.target === this) {
              closeIsoCertModal();
          }
      });
  </script>

